function skillsPane(){const m=members(st.capTeam);const dots=v=>`<span class="ppl-dots l${v}" aria-label="level ${v} of 3">${[1,2,3].map(i=>`<i class="${i<=v?"on":""}"></i>`).join("")}</span>`;
 const cov=SKILLS.map(([k])=>cover(k,2).length);
 const matrix=`<div class="ppl-heatwrap"><div class="ppl-sg"><div class="ppl-sr ppl-hh"><span></span>${SKILLS.map(s=>`<b title="${esc(s[1])}">${esc(s[1])}</b>`).join("")}</div>${m.map(p=>`<div class="ppl-sr"><button class="ppl-hn" data-ppl-open="${p.id}"><i class="av" style="background:${col(p.c)}">${ini(p.n)}</i>${esc(p.n)}</button>${SKILLS.map(([k,l])=>`<button class="ppl-sk" data-ppl-sk="${p.id}:${k}" aria-label="${esc(p.n)}, ${esc(l)}, level ${p.sk[k]||0}. Select to change.">${dots(p.sk[k]||0)}</button>`).join("")}</div>`).join("")}<div class="ppl-sr ppl-af"><span><b>People at level 2+</b><small class="muted"> whole organization</small></span>${cov.map((c,i)=>`<span class="ppl-ha ${c<=1?"bad":c<=2?"warn":"good"}" title="${c<=1?"Single point of failure":""}">${c}</span>`).join("")}</div></div></div>`;
 const req=`<div class="tablewrap"><table><thead><tr><th>Role</th><th>Needs</th><th>Team</th><th>People who meet it</th></tr></thead><tbody>${ROLEREQ.map(([r,rq,tm])=>{const ok=members(tm).filter(p=>rq.every(([k,l])=>(p.sk[k]||0)>=l));return `<tr data-nopick><td><b>${esc(r)}</b></td><td>${rq.map(([k,l])=>`<span class="pill info">${esc(SK[k])} ${l}+</span>`).join(" ")}</td><td>${esc(tm)}</td><td><span class="pill ${ok.length<=1?"bad":ok.length<=2?"warn":"good"}">${ok.length} of ${members(tm).length}</span> <span class="muted small">${ok.map(p=>esc(p.n.split(" ")[0])).join(", ")}</span></td></tr>`}).join("")}</tbody></table></div>`;
 const spof=SKILLS.filter((s,i)=>cov[i]<=1).map(s=>s[1]);
 return `${card("Skills matrix","Select a cell to change a level (none, basic, working, expert). Red numbers in the last row mean one person is the only expert.",`<div class="row" style="margin-bottom:10px">${TEAMS_ALL.map(t=>`<button class="chip" data-ppl-team="${esc(t)}" aria-pressed="${t===st.capTeam}">${esc(t)}</button>`).join("")}</div>${matrix}${spof.length?`<p class="small" style="margin-top:10px"><b>Single points of failure:</b> ${spof.map(esc).join(", ")}. A story for the next hiring plan.</p>`:""}`)}${card("Roles and what they need","A role is covered when someone has every required skill at the minimum level.",req)}`}
