 if(s<8||e>18)bad.push("Outside bookable hours (8 am to 6 pm)");
 st.bk.filter(x=>x.id!==b.id&&x.room===room&&x.d===d).forEach(x=>{if(occS<x.e-.001&&e>x.s-.001)bad.push("Overlaps "+x.t+" ("+hh(x.s)+" to "+hh(x.e)+")")});
 if(b.att>r.cap)bad.push(r.n+" seats "+r.cap+" and "+b.att+" are coming");
 const miss=(b.av||[]).filter(a=>!r.eq.includes(a));if(miss.length)warn.push(r.n+" lacks "+miss.join(", ").toLowerCase());
 if(b.hy&&r.tr.st==="Offline")warn.push(r.n+" Teams Room is offline, so hybrid will not work");
 if(r.tr.st==="Updating"&&b.hy)warn.push("Teams Room firmware is updating tonight");
