function roomUtil(){const d0=5,d1=9;const hrs=st.rooms.reduce((a,r)=>a+roomHours(r.id,d0,d1),0),cap=st.rooms.length*5*10;return {pct:hrs/cap*100,hrs,cap}}
function rightSize(){const out=[];st.bk.filter(b=>!b.gen&&b.d>=6&&b.d<=9||(b.gen&&b.d>=6&&b.d<=9&&b.att<=3)).forEach(b=>{const r=ROOM(b.room);if(r.cap<8||b.att>r.cap*.5)return;const alt=st.rooms.filter(x=>x.cap<r.cap&&x.cap>=b.att&&x.id!==b.room&&(b.av||[]).every(a=>x.eq.includes(a))&&(!b.hy||x.tr.st==="Online")&&!conflicts(b,x.id,b.d,b.s).bad.length&&!conflicts(b,x.id,b.d,b.s).warn.length).sort((a,b2)=>a.cap-b2.cap)[0];if(alt)out.push({b,from:r,to:alt})});return out.slice(0,5)}
