const KLEG=legend([["Employees","--good-f"],["AI agents","--u3"],["Contractors","--w1"],["Managed service providers","--p4"]]);
const uNow=(n,w)=>{const m=PM(n),x=w==null?st.org.week:w;return m.cap[x]>.5?m.tot[x]/m.cap[x]:(m.tot[x]>.5?9.99:null)};
