const pathTo=n=>{const out=[];let c=n,g=0;const H=HX();while(c&&g++<20){out.push(c);c=H.par.get(c)}return out};
const isMgr=n=>kindOf(n)==="human"&&kidsOf(n).some(c=>kindOf(c)==="human");
