function succCalc(role,used){const inc=who(role[1]);if(!inc)return [];const holders=new Set(KEYROLES.map(k=>k[1]));let C=reviewees().filter(d=>d.name!==inc.name&&!holders.has(d.name)&&(d.team===role[2]||pathTo(d.name).includes(role[1])||pathTo(inc.name).includes(mgrOfPerson(d.name))));C=C.map(d=>({n:d.name,s:REV(d.name).pot*10+(REV(d.name).draft||3)+hs(d.name+role[0])*2-(used.get(d.name)||0)*8})).sort((a,b)=>b.s-a.s).slice(0,3);
 C.forEach(c=>used.set(c.n,(used.get(c.n)||0)+1));
 return C.map((c,i)=>({n:c.n,ready:i===0&&hs(role[0])>.4?"Ready now":i===0?"1 to 2 years":i===1?"1 to 2 years":"3 or more years"}))}
function succOf(role){const o=PF.succ&&PF.succ[role[0]];if(o)return o;const k=DIR.length+"|"+PF.v;if(SUCCC.k!==k){SUCCC.k=k;SUCCC.m={};const used=new Map();KEYROLES.forEach(r=>{SUCCC.m[r[0]]=succCalc(r,used)})}return SUCCC.m[role[0]]||[]}
