function distChart(s){const g={1:.05,2:.12,3:.5,4:.25,5:.08},tot=Math.max(1,Object.values(s.dist).reduce((a,b)=>a+b,0)),mx=Math.max(.5,...Object.values(s.dist).map(v=>v/tot),...Object.values(g));
 return `<div class="pp2-hist wide" role="img" aria-label="Rating distribution">${[1,2,3,4,5].map(k=>`<div><b class="num" data-role="metric">${s.dist[k]}</b><span class="pp2-gb"><i style="height:${s.dist[k]/tot/mx*130}px;background:var(--accent)"></i><u style="bottom:${g[k]/mx*130}px"></u></span><small>${k} ${RLAB[k]}</small></div>`).join("")}</div>${legend([["Actual ratings so far","--accent"],["Dashed line: typical healthy curve","--muted"]])}<p class="muted small">The line is a typical healthy curve (5, 12, 50, 25, 8%). Mean rating ${s.gm?s.gm.toFixed(2):"n/a"}. ${stdChip("ninebox","Ratings feed the performance axis of the 9-box; potential is assessed separately.")}</p>`}
