 if(dim==="person"){const nm=scopeNames().filter(n=>who(n)&&who(n).kind!=="msp").map(n=>({n,u:avgU(PM(n),0,11)})).sort((a,b)=>b.u-a.u);rows=nm.slice(0,lim).map(x=>{const m=PM(x.n);return {lab:x.n,sub:pc(x.u),node:`<span class="pp2-hl">${pchip(x.n)}</span>`,cells:[...Array(NWK)].map((_,w)=>heatCell(cellVal({cap:m.cap,tot:m.tot,T:m.T},w,wt),`data-pp2-act="cell" data-a="${E(x.n)}|${w}" title="${E(x.n)}, week of ${WK[w].lab}: ${pc(cellVal({cap:m.cap,tot:m.tot,T:m.T},w,wt))}" aria-label="${E(x.n)} week of ${WK[w].lab}"`,false)).join("")}});rows.more=nm.length>lim?nm.length-lim:0}
 else{rows=groupRows(dim).map(([k,l])=>{const A=gagg(dim,k);const gn=groupNames(dim,k).length;const o=dim==="skill"||dim==="kind"||dim==="fam"||dim==="team"?ovWeeks(groupNames(dim,k)):new Float32Array(NWK);return {lab:l,sub:pc(avgU(A,0,11)),node:`<button class="pp2-hl pp2-lnk" data-pp2-act="rgrp" data-a="${dim}|${E(k)}">${E(l)}</button>`,cells:[...Array(NWK)].map((_,w)=>{const u=cellVal(A,w,wt);return heatCell(u,`data-pp2-act="rcell" data-a="${dim}|${E(k)}|${w}" title="${E(l)}, week of ${WK[w].lab}: ${pc(u)}${o[w]?", "+o[w]+" "+(o[w]===1?"person":"people")+" over 100%":""}" aria-label="${E(l)} week of ${WK[w].lab}"`,(o[w]>=2||o[w]>=.12*gn)&&(u==null||u<=1.0001))}).join("")}})}
