/* DC-01: one FTE model for every journey view. 140 hours is one FTE a month. What one recommended step can release is capped at REC_CAP_FTE,
   because one build rarely takes more than a few people's work off a single step and the sample volumes are invented. Modeled, not measured. */
const FTE_H=140,REC_CAP_FTE=2,REC_CAP_H=REC_CAP_FTE*FTE_H;
const capSave=h=>Math.min(h,REC_CAP_H);
