function jyDash(){syncJy();const L=JY.list;const all=L.flatMap(allBoxes);const S=L.map(j=>Object.assign({j},jStats(j)));const n=all.length;const linked=all.filter(x=>x.b.procs.length).length,auto=all.filter(x=>fmOf(x.b)!=="human").length,ag=all.filter(x=>fmOf(x.b)==="agentic").length,none=n-linked,many=all.filter(x=>x.b.procs.length>1).length;const hrs=all.reduce((a,x)=>a+x.b.min*x.b.vol/60,0);
 const cand=all.map(x=>({x,a:assess(x.b),r:rec(x.b)})).filter(o=>o.r.st==="cand").sort((a,b)=>b.r.usd-a.r.usd);const pains=all.filter(x=>x.b.pain).sort((a,b)=>a.b.em-b.b.em||b.b.vol-a.b.vol);
 return `<p class="story" data-role="story">${L.length} journeys with <b>${n} boxes</b>. <b>${Math.round(linked/n*100)}%</b> of boxes run on a linked process (${none} do not, so nothing fulfills them); ${many} boxes use more than one. <b>${Math.round(auto/n*100)}%</b> are fulfilled by rules or agents and ${ag} are agentic today. ${cand.length} more are candidates for a robot or an agent, worth about $${fmt(cand.reduce((a,o)=>a+o.r.usd,0))} a month (modeled). People spend <b>${fmt(hrs)} hours</b> a month inside these boxes. ${stdChip("cjm")}</p>
 <div class="statrow">${stat("Boxes linked to a process",Math.round(linked/n*100)+"%",none+" with nothing behind them",none?"warn":"")}${stat("Automation coverage",Math.round(auto/n*100)+"%",ag+" agentic")}${stat("Experience score",f1(METRICS.m_jr_xla.cur)+" of 5","weighted by volume")}${stat("Robot and agent candidates",String(cand.length),"modeled")}</div>
 ${card("Journeys","Health roll-up for each journey. Select one to open its map.",btHTML({id:"pp2_jys",cols:[{k:"n",label:"Journey",fmt:r=>`<button class="pp2-lnk" data-pp2-act="jopen" data-a="${r.id}"><b>${E(r.n)}</b></button>`},{k:"cat",label:"Area"},{k:"persona",label:"Main persona"},{k:"stages",label:"Stages"},{k:"boxes",label:"Boxes"},{k:"linked",label:"Linked",fmt:r=>`<span class="pill ${r.linked>=90?"good":r.linked>=60?"info":"warn"}">${r.linked}%</span>`},{k:"auto",label:"Rules or agents",fmt:r=>r.auto+"%"},{k:"xla",label:"Experience",fmt:r=>f1(r.xla)},{k:"min",label:"Minutes"},{k:"cost",label:"Cost per run",fmt:r=>"$"+fmt(r.cost)},{k:"wf",label:"Workflow",fmt:r=>r.wf||"Not promoted"}],rows:()=>S.map(s=>({id:s.j.id,n:s.j.n,cat:s.j.cat,persona:s.j.persona,stages:s.j.stages.length,boxes:s.n,linked:Math.round(s.linked*100),auto:Math.round(s.auto*100),xla:s.xla,min:s.min,cost:s.cost,wf:s.j.wf})),key:"id",h:260,rowH:46,facets:["cat","persona"],exportName:"journeys",open:id=>{JY.sel=id;st.tab.ppl_jrny=1;render()}}))}
 <div class="grid g2">${card("Biggest pain points","Lowest experience first, then by volume.",lrHTML({id:"pp2_jpain",groups:[{key:"a",label:"Pain points",rows:pains.slice(0,8).map(x=>({id:x.j.id+x.b.id,t:(window.JXR?JXR.tn(x.j,x.b)+" · ":"")+x.b.t,sub:x.j.n+" · "+x.b.pain,tag:x.b.em+" of 5",st:x.b.em<=2?"bad":"warn",go:()=>boxDrawer(x.j.id,x.b.id)}))}],limit:5}))}${card("Robot and agent candidates","Steps with enough volume that nothing automates yet. A robot where the steps repeat, an agent where judgment is needed.",lrHTML({id:"pp2_jcand",groups:[{key:"a",label:"Candidates",rows:cand.slice(0,8).map(o=>({id:o.x.j.id+o.x.b.id,t:(window.JXR?JXR.tn(o.x.j,o.x.b)+" · ":"")+o.x.b.t,sub:o.x.j.n+" · "+fmt(o.x.b.vol)+" a month · saves about $"+fmt(o.r.usd)+" a month",tag:o.r.k==="robot"?"Robot":"Agent",st:"good",go:()=>boxDrawer(o.x.j.id,o.x.b.id)}))}],limit:5}))}</div>`}
function fulfilTab(){if(window.JXR&&JXR.fulfilTab)return JXR.fulfilTab();const rows=JY.list.flatMap(j=>allBoxes(j).map(({b,s})=>{const a=assess(b),f=fmOf(b);return {id:j.id+"|"+b.id,j:j.n,stage:s.n,box:b.t,persona:b.who,fm:FMODE[f][0],lvl:AUTOL[maxAuto(b)][0],np:b.procs.length,vol:b.vol,min:b.min,hrs:Math.round(b.min*b.vol/60),score:a.score,verdict:recLabel(rec(b)),usd:Math.round(a.usd)}}));
 const bf={};rows.forEach(r=>bf[r.fm]=(bf[r.fm]||0)+1);
 return `<p class="story" data-role="story">Every box has a <b>fulfillment mode</b>. <b>Human</b>: a person does it. <b>Robot</b>: an RPA bot or a rule-based workflow, if this then that, with no reasoning and no model cost. <b>Agent</b>: an AI that reasons like a person and makes decisions, then acts or hands the work to another agent, with a named person accountable. Today ${bf.Human||0} boxes are human, ${bf.Robot||0} run on robots and ${bf.Agent||0} on agents. Steps that repeat the same way suit a robot; steps that need judgment suit an agent. The recommendation shows which, from volume, repeatability, data and safety.</p>${fmLeg()}
 ${card("Every box","Select a row for the processes behind it and the agentic assessment.",btHTML({id:"pp2_jful",cols:[{k:"box",label:"Box"},{k:"j",label:"Journey"},{k:"stage",label:"Stage"},{k:"persona",label:"Persona"},{k:"fm",label:"Mode",fmt:r=>`<span class="pp2-fm" style="--c:var(${r.fm==="Agent"?"--u3":r.fm==="Robot"?"--p4":"--faint"})">${r.fm}</span>`},{k:"lvl",label:"Best process level"},{k:"np",label:"Processes"},{k:"vol",label:"A month"},{k:"hrs",label:"Hours a month"},{k:"score",label:"Agent score",fmt:r=>`<span class="pill ${r.score>=70?"good":r.score>=45?"info":"mute"}">${r.score}</span>`},{k:"usd",label:"Saving a month ($)"},{k:"verdict",label:"Verdict"}],rows:()=>rows,key:"id",h:500,rowH:46,facets:["j","fm","verdict","persona"],groupBy:["j","fm","verdict"],exportName:"journey-boxes",open:id=>{const [a,b]=id.split("|");boxDrawer(a,b)}}))}`}
function procTab(){if(window.JXR&&JXR.procTab)return JXR.procTab();const M={};JY.list.forEach(j=>allBoxes(j).forEach(({b,s})=>b.procs.forEach(p=>{const k=p.src+"|"+p.ref;(M[k]=M[k]||{p,boxes:[]}).boxes.push({j,b})})));const rows=Object.values(M).sort((a,b)=>b.boxes.length-a.boxes.length);const sizes={0:0,1:0,2:0};JY.list.forEach(j=>allBoxes(j).forEach(({b})=>sizes[Math.min(2,b.procs.length)]++));
 return `<p class="story" data-role="story">Journey maps become integrated workflows through these links. A box usually runs on <b>one</b> process (${sizes[1]} boxes), sometimes on <b>several</b> (${sizes[2]}), and ${sizes[0]} run on <b>none</b>. A single process can also serve many boxes across journeys, so a fix to the laptop workflow improves every journey that uses it. ${stdChip("cjm")}</p>
 ${card("Processes and the boxes they serve","One row per process. The number is how many boxes depend on it.",`<div class="tscroll"><table><thead><tr><th>Process</th><th>Type</th><th>Automation</th><th>Boxes</th><th>Journeys</th><th>Experience</th><th></th></tr></thead><tbody>${rows.map(r=>{const js=[...new Set(r.boxes.map(x=>x.j.n))];const xla=mean(r.boxes.map(x=>x.b.em));const live=r.p.src==="WFX"&&window.WFX&&WFX.get(r.p.ref);return `<tr><td><b>${E(wfN(r.p))}</b></td><td>${r.p.src==="WFX"?"Workflow":"Screen process"}</td><td>${autoDots(procAuto(r.p))} <span class="small">${AUTOL[procAuto(r.p)][0]}</span></td><td class="num">${r.boxes.length}</td><td class="small">${js.map(E).join(", ")}</td><td class="num">${f1(xla)}</td><td>${live?`<button class="btn quiet" data-pp2-act="jopenwf" data-a="${E(r.p.ref)}">Designer</button>`:r.p.src==="PROC"?`<button class="btn quiet" data-go="${E(r.p.ref)}">Open</button>`:""}</td></tr>`}).join("")}</tbody></table></div>`)}
 ${card("Boxes with nothing behind them","These steps have no workflow, so nobody is accountable for how they run.",lrHTML({id:"pp2_jnone",groups:[{key:"a",label:"No process linked",rows:JY.list.flatMap(j=>allBoxes(j).filter(x=>!x.b.procs.length).map(x=>({id:j.id+x.b.id,t:x.b.t,sub:j.n+" · "+x.s.n+" · "+x.b.who,tag:"Link",st:"warn",go:()=>boxDrawer(j.id,x.b.id)})))}],limit:6}))}`}
function personaTab(){if(window.JXR&&JXR.personaTab)return JXR.personaTab();return `<p class="story" data-role="story">${PERSONAS.length} personas appear across the journeys. Each lane in the map belongs to one of them, so a change that helps the approver or the vendor shows up next to the change for the requester.</p><div class="grid g3">${PERSONAS.map(p=>{const L=JY.list.flatMap(j=>allBoxes(j).filter(x=>x.b.who===p).map(x=>Object.assign({j},x)));const n=L.length,vol=L.reduce((a,x)=>a+x.b.vol,0)||1,xla=L.reduce((a,x)=>a+x.b.em*x.b.vol,0)/vol;const who_=[...new Set(L.map(x=>x.j.n))];const worst=L.slice().sort((a,b)=>a.b.em-b.b.em)[0];return card(E(p),n+" boxes in "+who_.length+" journeys",`<div class="statrow" style="grid-template-columns:1fr 1fr">${stat("Experience",n?f1(xla)+" of 5":"n/a","volume weighted")}${stat("Hours a month",fmt(L.reduce((a,x)=>a+x.b.min*x.b.vol/60,0)),"spent in these boxes")}</div><p class="small">${who_.map(E).join(", ")||"Not in any journey yet"}</p>${worst?`<button class="btn quiet" data-pp2-act="jbox" data-a="${worst.j.id}|${worst.b.id}">Hardest moment: ${E(worst.b.t)}</button>`:""}`)}).join("")}</div>`}
